(function(){
 const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const by=s=>document.querySelector(s);
 const types={filters:'Pedido de filtros e peças',tires:'Pedido de pneus',general:'Pedido geral'};
 const fields=[['date','Data','date'],['time','Hora','time'],['manualNumber','Número do pedido','text'],['from','De / setor','text'],['to','Para / departamento','text'],['requester','Pedido feito por','text'],['department','Secretaria','text'],['responsible','Responsável do almoxarifado','text'],['contact','Telefone de contato','text'],['vehiclePrefix','Prefixo do veículo','text'],['plate','Placa','text'],['model','Descrição do veículo','text'],['year','Ano do veículo','text'],['patrimony','Nº patrimônio','text'],['mileage','KM / HR','text'],['driver','Motorista','text'],['mechanic','Mecânico / eletricista / outros','text'],['fleetResponsible','Responsável pela frota','text'],['internalMemo','Nº C.I.','text'],['serviceOrder','Nº da O.S.','text'],['protocol','Protocolo','text'],['situation','Situação do veículo','text'],['subject','Assunto','text'],['intro','Texto da solicitação','textarea'],['service','Serviço a realizar','textarea'],['notes','Observações','textarea'],['purchaseSignature','Responsável pelo pedido','text']];
 let current=null,draft=null,api=null,commit=null,vehicleList=[],saving=false;
 const uid=()=>crypto.randomUUID();
 const defaults=kind=>({id:uid(),kind,date:new Date().toISOString().slice(0,10),time:new Date().toTimeString().slice(0,5),manualNumber:'',from:'ALMOXARIFADO',to:'DEPARTAMENTO DE COMPRAS',requester:'RICAEL',department:'',responsible:'RICAEL',contact:'',vehiclePrefix:'',plate:'',model:'',year:'',patrimony:'',mileage:'',driver:'',mechanic:'',fleetResponsible:'',internalMemo:'',serviceOrder:'',protocol:'',situation:'',subject:kind==='tires'?'Pedido para Compra Almoxarifado':'',intro:kind==='tires'?'Cumprimentando-o cordialmente, venho através deste solicitar a compra dos itens abaixo, para uso dos veículos da secretaria informada.':'',service:'',notes:'',purchaseSignature:'',status:'Pendente',items:[{code:'',quantity:'1',description:'',brand:'',unitPrice:''}]});
 function normalize(record){const kind=record.kind||'general';const d={...defaults(kind),...record};d.items=Array.isArray(record.items)&&record.items.length?record.items.map(x=>({...x})): [{code:'',quantity:record.quantity||'1',description:record.item||'',brand:'',unitPrice:''}];d.manualNumber=record.number||record.manualNumber||'';return d}
 const label=(s)=>types[s]||types.general;
 const fieldHtml=([key,title,type])=>`<label class="order-field"><span>${title}</span>${type==='textarea'?`<textarea name="${key}" rows="3">${E(draft[key])}</textarea>`:`<input name="${key}" type="${type}" value="${E(draft[key])}" ${key==='date'?'required':''}>`}</label>`;
 function itemRow(x,i){return `<div class="order-item" data-item-index="${i}"><input aria-label="Código" placeholder="Código" data-item="code" value="${E(x.code)}"><input aria-label="Quantidade" placeholder="Qtd." type="number" min="0.01" step="any" data-item="quantity" value="${E(x.quantity)}"><input aria-label="Descrição" placeholder="Descrição do material" data-item="description" value="${E(x.description)}"><input aria-label="Marca" placeholder="Marca" data-item="brand" value="${E(x.brand)}"><input aria-label="Valor unitário" placeholder="R$" data-item="unitPrice" value="${E(x.unitPrice)}"><button type="button" title="Remover item" data-remove-item="${i}">×</button></div>`}
 function ensureDialog(){if(by('#purchase-dialog'))return;const dialog=document.createElement('dialog');dialog.id='purchase-dialog';dialog.innerHTML=`<form id="purchase-form"><div class="order-modal-head"><div><small>FROTA360 · DOCUMENTOS</small><h2 id="purchase-title">Pedido de compras</h2></div><button type="button" data-close-order aria-label="Fechar">✕</button></div><div class="order-modal-body"><div class="order-tabs"><button type="button" data-order-type="filters">Filtros / peças</button><button type="button" data-order-type="tires">Pneus</button><button type="button" data-order-type="general">Geral</button></div><div class="order-edit-layout"><div class="order-form-panel"><h3>Informações do pedido</h3><div class="order-form-grid" id="order-fields"></div><h3>Relação de itens</h3><p class="muted">Adicione ou remova linhas. Todos os campos são editáveis.</p><div class="order-item-header"><span>CÓDIGO</span><span>QUANTIDADE</span><span>DESCRIÇÃO</span><span>MARCA</span><span>VALOR UNIT.</span><span></span></div><div id="order-items"></div><button type="button" class="ghost" id="add-order-item">Adicionar item</button></div><div class="order-preview-panel"><div class="row-between"><h3>Prévia do documento</h3><button type="button" class="ghost" id="print-order">Imprimir / salvar PDF</button></div><div id="order-document"></div></div></div></div><div class="order-modal-footer"><span id="order-save-message">Alterações ainda não salvas</span><div><button class="ghost" type="button" data-close-order>Cancelar</button><button class="primary" type="submit" id="save-order">Salvar pedido</button></div></div></form>`;document.body.appendChild(dialog);dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.querySelectorAll('[data-close-order]').forEach(b=>b.addEventListener('click',()=>dialog.close()));dialog.querySelector('#add-order-item').addEventListener('click',()=>{collect();draft.items.push({code:'',quantity:'1',description:'',brand:'',unitPrice:''});refresh()});dialog.querySelector('#order-items').addEventListener('click',e=>{const b=e.target.closest('[data-remove-item]');if(!b)return;collect();draft.items.splice(Number(b.dataset.removeItem),1);if(!draft.items.length)draft.items.push({code:'',quantity:'1',description:'',brand:'',unitPrice:''});refresh()});dialog.querySelectorAll('[data-order-type]').forEach(b=>b.addEventListener('click',()=>{collect();draft.kind=b.dataset.orderType;refresh()}));dialog.querySelector('#purchase-form').addEventListener('input',()=>{collect();refreshPreview()});dialog.querySelector('#print-order').addEventListener('click',()=>{collect();refreshPreview();const print=by('#print-layout');print.innerHTML=by('#order-document').innerHTML;document.body.classList.add('printing-order');window.print()});dialog.querySelector('#purchase-form').addEventListener('submit',save);
 window.addEventListener('afterprint',()=>document.body.classList.remove('printing-order'));const print=document.createElement('div');print.id='print-layout';document.body.appendChild(print)}
 function collect(){const form=by('#purchase-form');for(const f of fields){const el=form.querySelector('[name="'+f[0]+'"]');if(el)draft[f[0]]=el.value}draft.items=Array.from(form.querySelectorAll('[data-item-index]')).map(row=>Object.fromEntries(Array.from(row.querySelectorAll('[data-item]')).map(el=>[el.dataset.item,el.value])))}
 function refresh(){by('#purchase-title').textContent=label(draft.kind);by('#order-fields').innerHTML=fields.map(fieldHtml).join('');by('#order-items').innerHTML=draft.items.map(itemRow).join('');by('#purchase-dialog').querySelectorAll('[data-order-type]').forEach(b=>b.classList.toggle('selected',b.dataset.orderType===draft.kind));refreshPreview()}
 const money=s=>{const n=Number(String(s||'').replace(/\./g,'').replace(',','.'));return Number.isFinite(n)&&String(s||'').trim()?n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'}):'—'};
 const date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('pt-BR'):'—';
 function documentHtml(d){const isTire=d.kind==='tires';const lines=d.items.filter(x=>Object.values(x).some(v=>String(v||'').trim()));const parts=lines.map(x=>`<tr><td>${E(x.code)}</td><td>${E(x.quantity)}</td><td>${E(x.description)}</td><td>${E(x.brand)}</td><td>${money(x.unitPrice)}</td></tr>`).join('');const left=`<div><b>DE:</b> ${E(d.from)}</div><div><b>PARA:</b> ${E(d.to)}</div>`;const right=`<div><b>HORA:</b> ${E(d.time)}　 <b>Nº:</b> ${E(d.manualNumber||'Automático')}</div><div><b>DATA:</b> ${date(d.date)}</div>`;const truckInfo=`<h3>DADOS DO VEÍCULO</h3><div class="doc-grid"><div><b>PREFIXO:</b> ${E(d.vehiclePrefix)}</div><div><b>PLACA:</b> ${E(d.plate)}</div><div><b>SECRETARIA:</b> ${E(d.department)}</div><div><b>KM/HR:</b> ${E(d.mileage)}</div><div class="doc-wide"><b>DESCRIÇÃO DO VEÍCULO:</b> ${E(d.model)}</div><div><b>ANO:</b> ${E(d.year)}</div><div><b>PATRIMÔNIO:</b> ${E(d.patrimony)}</div><div><b>MOTORISTA:</b> ${E(d.driver)}</div><div><b>MEC./ELET.:</b> ${E(d.mechanic)}</div><div><b>TELEFONE:</b> ${E(d.contact)}</div><div><b>Nº C.I.:</b> ${E(d.internalMemo)}</div><div><b>Nº O.S.:</b> ${E(d.serviceOrder)}</div><div><b>RESP. FROTA:</b> ${E(d.fleetResponsible)}</div><div><b>PROTOCOLO:</b> ${E(d.protocol)}</div><div><b>SITUAÇÃO:</b> ${E(d.situation)}</div></div><div class="doc-note"><b>SERVIÇO E OBSERVAÇÕES:</b><p>${E(d.service)}</p></div>`;return `<article class="print-document"><div class="doc-letterhead"><div class="doc-seal">PM</div><div><strong>Prefeitura Municipal de Sorriso</strong><div>ESTADO DE MATO GROSSO</div><small>Sorriso: A Capital Nacional do Agronegócio</small></div></div><h2>PEDIDO DE COMPRAS ALMOXARIFADO</h2><div class="doc-ident"><div>${left}</div><div>${right}</div></div>${isTire?`<p><b>RESPONSÁVEL ALMOXARIFADO:</b> ${E(d.responsible)}</p><div class="doc-request"><b>Assunto:</b> ${E(d.subject)}<p>${E(d.intro)}</p><strong>${E(lines.map(x=>x.description).join(' / '))}　${E(d.vehiclePrefix)}</strong><p>Para uso dos veículos da secretaria de ${E(d.department)}, conforme a relação abaixo.</p></div>`:truckInfo}<h3>RELAÇÃO DE ${isTire?'ITENS':'PEÇAS'}</h3><table class="doc-items"><thead><tr><th>CÓDIGO</th><th>QUANT.</th><th>DESCRIÇÃO</th><th>MARCA</th><th>VALOR UNIT.</th></tr></thead><tbody>${parts||'<tr><td colspan="5">Nenhum item preenchido</td></tr>'}</tbody></table><div class="doc-note"><b>OBSERVAÇÕES:</b><p>${E(d.notes)}</p></div><p class="doc-maker">PEDIDO FEITO POR: ${E(d.requester)}</p><div class="doc-signatures"><span>DEPARTAMENTO DE COMPRAS</span><span>${E(d.purchaseSignature||'RESPONSÁVEL PELO PEDIDO')}</span></div><footer>Av. Porto Alegre, 2525 · Sorriso · Mato Grosso</footer></article>`}
 function refreshPreview(){by('#order-document').innerHTML=documentHtml(draft)}
 function render(orders,search){let list=[...orders].reverse().filter(o=>[o.number,o.item,o.department,o.requester,o.kind,...(o.items||[]).map(x=>x.description)].some(x=>String(x||'').toLowerCase().includes(String(search||'').toLowerCase())));return `<div class="panel"><div class="panel-head"><div><h2>Pedidos de compras</h2><p>Modelos do almoxarifado com campos editáveis e impressão</p></div><span class="muted">${list.length} pedidos</span></div><div class="order-template-choices"><button data-create-order="filters"><strong>Pedido de filtros e peças</strong><small>Ficha do veículo, relação de filtros e observações</small></button><button data-create-order="tires"><strong>Pedido de pneus</strong><small>Solicitação de compra, itens, marca e valores</small></button><button data-create-order="general"><strong>Pedido geral</strong><small>Solicitação livre de materiais</small></button></div><input class="search" style="margin:18px 0" placeholder="Pesquisar pedidos..." data-search value="${E(search)}"><div class="table-wrap"><table><thead><tr><th>NÚMERO</th><th>DATA</th><th>MODELO</th><th>VEÍCULO / SECRETARIA</th><th>ITENS</th><th>EDIÇÃO</th></tr></thead><tbody>${list.map(o=>`<tr><td class="code">${E(o.number)}</td><td>${date(o.date)}</td><td>${label(o.kind||'general')}</td><td>${E(o.vehiclePrefix||'—')}<small class="muted"> · ${E(o.department)}</small></td><td>${o.items?.length||1}</td><td><button class="link" data-edit-order="${E(o.id)}">Abrir / editar</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">Nenhum pedido cadastrado.</td></tr>'}</tbody></table></div></div>`}
 function open(kind,record,context){ensureDialog();api=context.api;commit=context.commit;vehicleList=context.vehicles||[];current=record||null;draft=record?normalize(record):defaults(kind);refresh();by('#order-dialog').showModal();by('#order-save-message').textContent='Todos os campos podem ser alterados';}
 async function save(e){e.preventDefault();if(saving)return;collect();if(!draft.items.some(x=>String(x.description||'').trim())){by('#order-save-message').textContent='Informe ao menos um item com descrição.';return}saving=true;const btn=by('#save-order');btn.disabled=true;btn.textContent='Salvando...';try{const clean={...draft,item:draft.items.map(x=>x.description).filter(Boolean).join(' / '),quantity:draft.items.reduce((sum,x)=>sum+(Number(x.quantity)||0),0),requester:draft.requester||'Almoxarifado',department:draft.department||'Não informado'};if(current){const result=await api('records/orders/'+current.id,'PUT',clean);commit(result.record,'update')}else{const result=await api('records/orders','POST',clean);commit(result.record,'create')}by('#order-dialog').close()}catch(err){by('#order-save-message').textContent=err.message}finally{saving=false;btn.disabled=false;btn.textContent='Salvar pedido'}}
 const baseRefresh=refresh;
 refresh=function(){
  baseRefresh();
  if(!vehicleList.length)return;
  const wrapper=document.createElement('label');wrapper.className='order-field';wrapper.style.gridColumn='1 / -1';
  wrapper.innerHTML='<span>Preencher dados a partir de veículo cadastrado (opcional)</span><select id="order-vehicle-select"><option value="">Escolher veículo...</option>'+vehicleList.map(v=>'<option value="'+E(v.id)+'">'+E(v.prefix)+' · '+E(v.model)+'</option>').join('')+'</select>';
  by('#order-fields').prepend(wrapper);
  wrapper.querySelector('select').addEventListener('change',e=>{const v=vehicleList.find(x=>x.id===e.target.value);if(!v)return;collect();draft.vehiclePrefix=v.prefix||'';draft.plate=v.plate||'';draft.model=v.model||'';draft.department=v.department||'';draft.year=v.year||'';draft.patrimony=v.patrimony||'';draft.mileage=v.mileage||'';refresh()});
 };
 window.PurchaseOrders={render,open,types};
})();
